[metadata] {"type": "create", "filePath": "/app/output/styles.css", "content": "/* LearnForge - Modern Bold Professional CSS */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

:root {
  --primary: #000000;
  --accent: #E6FF32;
  --accent-secondary: #7F2A23;
  --blue: #4361EE;
  --blue-dark: #3730A3;
  --coral: #FF6B6B;
  --green: #10B981;
  --white: #FFFFFF;
  --gray-50: #F9FAFB;
  --gray-100: #F3F4F6;
  --gray-200: #E5E7EB;
  --gray-300: #D1D5DB;
  --gray-400: #9CA3AF;
  --gray-500: #6B7280;
  --gray-600: #4B5563;
  --gray-700: #374151;
  --gray-800: #1F2937;
  --gray-900: #111827;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -1px rgba(0,0,0,0.06);
  --shadow-md: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -2px rgba(0,0,0,0.05);
  --shadow-lg: 0 20px 25px -5px rgba(0,0,0,0.1), 0 10px 10px -5px rgba(0,0,0,0.04);
  --shadow-xl: 0 25px 50px -12px rgba(0,0,0,0.25);
  --radius: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--gray-800);
  background: var(--white);
  -webkit-font-smoothing: antialiased;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-weight: 700;
  line-height: 1.2;
  color: var(--primary);
}

h1 { font-size: clamp(2.5rem, 5vw, 4rem); font-weight: 800; }
h2 { font-size: clamp(2rem, 4vw, 3rem); }
h3 { font-size: clamp(1.5rem, 3vw, 2rem); }
h4 { font-size: 1.25rem; }

p { color: var(--gray-600); }

a {
  color: var(--blue);
  text-decoration: none;
  transition: color 0.2s;
}

a:hover { color: var(--blue-dark); }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  font-size: 1rem;
  font-weight: 600;
  border-radius: var(--radius);
  border: none;
  cursor: pointer;
  transition: all 0.2s ease;
  text-decoration: none;
}

.btn-primary {
  background: var(--primary);
  color: var(--white);
}

.btn-primary:hover {
  background: var(--gray-800);
  color: var(--white);
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.btn-secondary {
  background: var(--white);
  color: var(--primary);
  border: 2px solid var(--gray-200);
}

.btn-secondary:hover {
  border-color: var(--primary);
  color: var(--primary);
}

.btn-accent {
  background: var(--accent);
  color: var(--primary);
}

.btn-accent:hover {
  background: #d4eb2d;
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.btn-lg {
  padding: 18px 36px;
  font-size: 1.125rem;
}

/* Navigation */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--gray-100);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.nav-logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary);
  text-decoration: none;
}

.nav-logo span {
  color: var(--accent-secondary);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-link {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--gray-600);
  text-decoration: none;
  transition: color 0.2s;
}

.nav-link:hover {
  color: var(--primary);
}

.nav-cta {
  margin-left: 16px;
}

/* Hero Section */
.hero {
  padding: 160px 0 80px;
  background: linear-gradient(180deg, var(--gray-50) 0%, var(--white) 100%);
}

.hero-content {
  text-align: center;
  max-width: 900px;
  margin: 0 auto;
}

.hero-badge {
  display: inline-block;
  padding: 8px 16px;
  background: var(--accent);
  color: var(--primary);
  font-size: 0.875rem;
  font-weight: 600;
  border-radius: 100px;
  margin-bottom: 24px;
}

.hero h1 {
  margin-bottom: 24px;
}

.hero-subtitle {
  font-size: 1.25rem;
  color: var(--gray-500);
  max-width: 700px;
  margin: 0 auto 40px;
}

.hero-cta {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

/* Tab Switch */
.tab-switch {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin-top: 48px;
  padding: 6px;
  background: var(--gray-100);
  border-radius: 100px;
  width: fit-content;
  margin-left: auto;
  margin-right: auto;
}

.tab-switch-btn {
  padding: 12px 24px;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--gray-500);
  background: transparent;
  border: none;
  border-radius: 100px;
  cursor: pointer;
  transition: all 0.3s ease;
}

.tab-switch-btn.active {
  background: var(--white);
  color: var(--primary);
  box-shadow: var(--shadow);
}

.tab-content {
  display: none;
  margin-top: 32px;
  padding: 32px;
  background: var(--white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  text-align: left;
}

.tab-content.active {
  display: block;
  animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Preview mockups */
.preview-mockup {
  background: var(--gray-50);
  border-radius: var(--radius);
  padding: 24px;
  border: 1px solid var(--gray-200);
}

.preview-mockup-header {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}

.preview-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
}

.preview-dot.red { background: var(--coral); }
.preview-dot.yellow { background: #FBBF24; }
.preview-dot.green { background: var(--green); }

.preview-bar {
  height: 40px;
  background: var(--gray-200);
  border-radius: 8px;
  margin-bottom: 12px;
}

.preview-content {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 16px;
}

.preview-sidebar {
  background: var(--gray-200);
  border-radius: 8px;
  padding: 16px;
}

.preview-sidebar-item {
  height: 12px;
  background: var(--gray-300);
  border-radius: 4px;
  margin-bottom: 12px;
}

.preview-main {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.preview-card {
  background: var(--gray-200);
  border-radius: 8px;
  height: 80px;
}

/* Stats Bar */
.stats-bar {
  padding: 64px 0;
  background: var(--primary);
  color: var(--white);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 48px;
  text-align: center;
}

.stat-item h3 {
  font-size: 3rem;
  font-weight: 800;
  color: var(--white);
  margin-bottom: 8px;
}

.stat-item p {
  color: var(--gray-400);
  font-size: 1rem;
}

/* Products Grid */
.products {
  padding: 100px 0;
}

.section-header {
  text-align: center;
  max-width: 700px;
  margin: 0 auto 64px;
}

.section-header h2 {
  margin-bottom: 16px;
}

.section-header p {
  font-size: 1.125rem;
}

.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.product-card {
  padding: 32px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  transition: all 0.3s ease;
  text-decoration: none;
}

.product-card:hover {
  border-color: var(--blue);
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.product-icon {
  width: 56px;
  height: 56px;
  background: var(--gray-50);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 20px;
}

.product-card h4 {
  margin-bottom: 8px;
  color: var(--primary);
}

.product-card p {
  font-size: 0.9375rem;
}

/* Why Choose Us Tabs */
.why-choose {
  padding: 100px 0;
  background: var(--gray-50);
}

.why-choose-tabs {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-bottom: 48px;
  flex-wrap: wrap;
}

.why-tab {
  padding: 14px 24px;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--gray-600);
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 100px;
  cursor: pointer;
  transition: all 0.2s;
}

.why-tab:hover {
  border-color: var(--blue);
  color: var(--blue);
}

.why-tab.active {
  background: var(--primary);
  color: var(--white);
  border-color: var(--primary);
}

.why-content {
  display: none;
  max-width: 900px;
  margin: 0 auto;
}

.why-content.active {
  display: block;
  animation: fadeIn 0.3s ease;
}

.why-content h3 {
  text-align: center;
  margin-bottom: 32px;
}

.why-list {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
  list-style: none;
}

.why-list li {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 20px;
  background: var(--white);
  border-radius: var(--radius);
  font-weight: 500;
}

.why-list li::before {
  content: "✓";
  width: 24px;
  height: 24px;
  background: var(--accent);
  color: var(--primary);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.875rem;
  font-weight: 700;
  flex-shrink: 0;
}

/* Global Scale */
.global-scale {
  padding: 100px 0;
  text-align: center;
}

.global-scale h2 {
  margin-bottom: 48px;
}

.global-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.global-item {
  padding: 32px;
  background: var(--gray-50);
  border-radius: var(--radius-lg);
}

.global-item h4 {
  margin-bottom: 8px;
}

.global-item p {
  font-size: 0.9375rem;
}

/* AI Automations */
.ai-automations {
  padding: 100px 0;
  background: var(--primary);
  color: var(--white);
}

.ai-automations h2 {
  color: var(--white);
  text-align: center;
  margin-bottom: 48px;
}

.ai-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.ai-item {
  padding: 24px;
  background: rgba(255,255,255,0.1);
  border-radius: var(--radius);
  text-align: center;
}

.ai-item h4 {
  color: var(--white);
  margin-bottom: 8px;
}

.ai-item p {
  color: var(--gray-400);
  font-size: 0.875rem;
}

/* Testimonials Carousel */
.testimonials {
  padding: 100px 0;
  background: var(--gray-50);
}

.testimonials h2 {
  text-align: center;
  margin-bottom: 48px;
}

.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform 0.5s ease;
}

.testimonial-card {
  flex: 0 0 calc(33.333% - 16px);
  margin-right: 24px;
  padding: 32px;
  background: var(--white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow);
}

.testimonial-quote {
  font-size: 1.0625rem;
  line-height: 1.7;
