.integrations h2 {
  text-align: center;
  margin-bottom: 16px;
}

.integrations > p {
  text-align: center;
  margin-bottom: 48px;
}

.integrations-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 16px;
