/* Social Proof */
.social-proof {
  padding: 80px 0;
  background: var(--primary);
  text-align: center;
}

.social-proof h2 {
  color: var(--white);
  margin-bottom: 24px;
}

.social-proof p {
  color: var(--gray-400);
  margin-bottom: 32px;
}

/* FAQ Accordion */
.faq {
  padding: 100px 0;
}

.faq h2 {
  text-align: center;
  margin-bottom: 48px;
}

.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--gray-200);
}

.faq-question {
  width: 100%;
  padding: 24px 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: none;
  border: none;
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--primary);
  cursor: pointer;
  text-align: left;
}

.faq-question:hover {
  color: var(--blue);
}

.faq-icon {
  width: 24px;
  height: 24px;
  position: relative;
  flex-shrink: 0;
}

.faq-icon::before,
.faq-icon::after {
  content: "";
  position: absolute;
  background: currentColor;
  transition: transform 0.3s ease;
}

.faq-icon::before {
  width: 16px;
  height: 2px;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

.faq-icon::after {
  width: 2px;
  height: 16px;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

.faq-item.active .faq-icon::after {
  transform: translate(-50%, -50%) rotate(90deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.faq-answer p {
  padding-bottom: 24px;
  line-height: 1.7;
}

.faq-item.active .faq-answer {
  max-height: 200px;
}

/* CTA Banner */
.cta-banner {
  padding: 80px 0;
  background: linear-gradient(135deg, var(--blue) 0%, var(--blue-dark) 100%);
  text-align: center;
}

.cta-banner h2 {
  color: var(--white);
  margin-bottom: 16px;
}

.cta-banner p {
  color: rgba(255,255,255,0.8);
  margin-bottom: 32px;
  font-size: 1.125rem;
}

.cta-banner .btn {
  background: var(--white);
  color: var(--primary);
}

.cta-banner .btn:hover {
  background: var(--accent);
}

/* Footer */
.footer {
  padding: 80px 0 40px;
  background: var(--gray-900);
  color: var(--gray-400);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: 48px;
  margin-bottom: 48px;
}

.footer-brand h3 {
  color: var(--white);
  font-size: 1.5rem;
  margin-bottom: 16px;
}

.footer-brand p {
  font-size: 0.9375rem;
  line-height: 1.7;
}

.footer-col h4 {
  color: var(--white);
  margin-bottom: 20px;
  font-size: 0.9375rem;
}

.footer-col ul {
  list-style: none;
}

.footer-col li {
  margin-bottom: 12px;
}

.footer-col a {
  color: var(--gray-400);
  font-size: 0.9375rem;
  transition: color 0.2s;
}

.footer-col a:hover {
  color: var(--white);
}

.footer-bottom {
  padding-top: 40px;
  border-top: 1px solid var(--gray-800);
  text-align: center;
  font-size: 0.875rem;
}

/* Page-specific styles */
.page-hero {
  padding: 140px 0 80px;
  background: var(--gray-50);
  text-align: center;
}

.page-hero h1 {
  margin-bottom: 16px;
}

.page-hero p {
  font-size: 1.25rem;
  max-width: 600px;
  margin: 0 auto;
}

/* Feature cards */
.feature-card {
  padding: 32px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
}

.feature-card h4 {
  margin-bottom: 12px;
}

.feature-card p {
  font-size: 0.9375rem;
}

.feature-icon {
  width: 64px;
  height: 64px;
  background: linear-gradient(135deg, var(--blue) 0%, var(--blue-dark) 100%);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  color: var(--white);
  margin-bottom: 20px;
}

/* Three steps */
.three-steps {
  padding: 100px 0;
}

.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.step-item {
  text-align: center;
  padding: 32px;
}

.step-number {
  width: 64px;
  height: 64px;
  background: var(--accent);
  color: var(--primary);
  font-size: 1.5rem;
  font-weight: 800;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 24px;
}

.step-item h4 {
  margin-bottom: 12px;
}

/* Tools Grid */
.tools-grid {
  padding: 100px 0;
  background: var(--gray-50);
}

.tools-grid h2 {
  text-align: center;
  margin-bottom: 48px;
}

.tools-categories {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.tool-category {
  background: var(--white);
  padding: 24px;
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
}

.tool-category h4 {
  margin-bottom: 16px;
  color: var(--blue);
}

.tool-category ul {
  list-style: none;
}

.tool-category li {
  padding: 8px 0;
  font-size: 0.9375rem;
  color: var(--gray-600);
  border-bottom: 1px solid var(--gray-100);
}

.tool-category li:last-child {
  border-bottom: none;
}

/* Spotlight */
.spotlight {
  padding: 100px 0;
}

.spotlight-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.spotlight-card {
  padding: 32px;
  background: var(--gray-50);
  border-radius: var(--radius-lg);
  text-align: center;
}

.spotlight-card h4 {
  margin-bottom: 8px;
}

.spotlight-card p {
  font-size: 0.9375rem;
}

/* Product Demo Accordion */
.demo-accordion {
  padding: 80px 0;
}

.demo-wrapper {
  max-width: 900px;
  margin: 0 auto;
}

.demo-item {
  border: 1px solid var(--gray-200);
  border-radius: var(--radius);
  margin-bottom: 12px;
  overflow: hidden;
}

.demo-header {
  width: 100%;
  padding: 20px 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--gray-50);
  border: none;
  font-size: 1rem;
  font-weight: 600;
  color: var(--primary);
  cursor: pointer;
}

.demo-header:hover {
  background: var(--gray-100);
}

.demo-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.demo-content-inner {
  padding: 24px;
  background: var(--white);
}

.demo-item.active .demo-content {
  max-height: 400px;
}

.demo-item.active .faq-icon::after {
  transform: translate(-50%, -50%) rotate(90deg);
}

/* Resources */
.resources {
  padding: 100px 0;
  background: var(--gray-50);
}

.resources-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.resource-card {
  padding: 32px;
  background: var(--white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
  text-decoration: none;
  transition: all 0.3s ease;
}

.resource-card:hover {
  border-color: var(--blue);
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.resource-card h4 {
  margin-bottom: 8px;
  color: var(--primary);
}

.resource-card p {
  font-size: 0.9375rem;
}

/* Membership stats */
.membership-stats {
  padding: 80px 0;
  background: var(--primary);
}

.stats-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  text-align: center;
}

.stat-box {
  padding: 32px;
}

.stat-box h3 {
  color: var(--accent);
  font-size: 2.5rem;
  margin-bottom: 8px;
}

.stat-box h4 {
  color: var(--white);
  margin-bottom: 8px;
}

.stat-box p {
  color: var(--gray-400);
  font-size: 0.9375rem;
}

/* Responsive */
@media (max-width: 1024px) {
  .products-grid,
  .ai-grid,
  .tools-categories {
    grid-template-columns: repeat(2, 1fr);
  }

  .why-list {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .integrations-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
  }

  .hero {
    padding: 120px 0 60px;
  }

  h1 { font-size: 2rem; }
  h2 { font-size: 1.75rem; }

  .stats-grid,
  .products-grid,
  .global-grid,
  .ai-grid,
  .pricing-cards,
  .steps-grid,
  .spotlight-grid,
  .resources-grid,
  .tools-categories {
    grid-template-columns: 1fr;
  }

  .testimonial-card {
    flex: 0 0 100%;
    margin-right: 0;
  }

  .preview-content {
    grid-template-columns: 1fr;
  }

  .preview-sidebar {
    display: none;
  }

  .integrations-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }
}
