}

.carousel-btn {
  width: 48px;
  height: 48px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 50%;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  transition: all 0.2s;
}

.carousel-btn:hover {
  background: var(--primary);
  color: var(--white);
  border-color: var(--primary);
}

/* Pricing Overview */
.pricing-overview {
  padding: 100px 0;
}

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-bottom: 48px;
}

.pricing-card {
  padding: 40px 32px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  text-align: center;
  transition: all 0.3s ease;
}

.pricing-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.pricing-card.featured {
  background: var(--primary);
  border-color: var(--primary);
  color: var(--white);
}

.pricing-card.featured h4,
.pricing-card.featured .pricing-amount {
  color: var(--white);
}

.pricing-card.featured p {
  color: var(--gray-400);
}

.pricing-amount {
  font-size: 3rem;
  font-weight: 800;
  color: var(--primary);
  margin-bottom: 8px;
}

.pricing-amount span {
  font-size: 1rem;
  font-weight: 400;
  color: var(--gray-500);
}

.pricing-features {
  list-style: none;
  margin: 24px 0;
  text-align: left;
}

.pricing-features li {
  padding: 8px 0;
  font-size: 0.9375rem;
  display: flex;
  align-items: center;
  gap: 8px;
}

.pricing-features li::before {
  content: "✓";
  color: var(--green);
  font-weight: 700;
}

.pricing-note {
  text-align: center;
  color: var(--gray-500);
  font-size: 0.9375rem;
}

.pricing-note strong {
  color: var(--gray-700);
}

/* Integrations */
.integrations {
  padding: 100px 0;
  background: var(--gray-50);
}

.integrations h2 {
  text-align: center;
  margin-bottom: 16px;
}

.integrations > p {
  text-align: center;
  margin-bottom: 48px;
}

.integrations-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 16px;
}

.integration-item {
  padding: 20px;
  background: var(--white);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 600;
  color: var(--gray-600);
  border: 1px solid var(--gray-200);
  transition: all 0.2s;
}

.integration-item:hover {
  border-color: var(--blue);
  color: var(--blue);
  transform: translateY(-2px);
}

/* Social Proof */
.social-proof {
  padding: 80px 0;
  background: var(--primary);
  text-align: center;
}

.social-proof h2 {
  color: var(--white);
  margin-bottom: 24px;
}

.social-proof p {
  color: var(--gray-400);
  margin-bottom: 32px;
}

/* FAQ Accordion */
.faq {
  padding: 100px 0;
}

.faq h2 {
  text-align: center;
  margin-bottom: 48px;
}

.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--gray-200);
}

.faq-question {
  width: 100%;
  padding: 24px 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: none;
  border: none;
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--primary);
  cursor: pointer;
  text-align: left;
}

.faq-question:hover {
  color: var(--blue);
}

.faq-icon {
  width: 24px;
  height: 24px;
  position: relative;
  flex-shrink: 0;
}

.faq-icon::before,
.faq-icon::after {
  content: "";
  position: absolute;
  background: currentColor;
  transition: transform 0.3s ease;
}

.faq-icon::before {
  width: 16px;
  height: 2px;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

.faq-icon::after {
  width: 2px;
  height: 16px;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

.faq-item.active .faq-icon::after {
  transform: translate(-50%, -50%) rotate(90deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.faq-answer p {
  padding-bottom: 24px;
  line-height: 1.7;
}

.faq-item.active .faq-answer {
  max-height: 200px;
}

/* CTA Banner */
.cta-banner {
  padding: 80px 0;
  background: linear-gradient(135deg, var(--blue) 0%, var(--blue-dark) 100%);
  text-align: center;
}

.cta-banner h2 {
  color: var(--white);
  margin-bottom: 16px;
}

.cta-banner p {
  color: rgba(255,255,255,0.8);
  margin-bottom: 32px;
  font-size: 1.125rem;
}

.cta-banner .btn {
  background: var(--white);
  color: var(--primary);
}

.cta-banner .btn:hover {
  background: var(--accent);
}

