}

.footer-col ul {
  list-style: none;
}

.footer-col li {
  margin-bottom: 12px;
}

.footer-col a {
  color: var(--gray-400);
  font-size: 0.9375rem;
  transition: color 0.2s;
}

.footer-col a:hover {
  color: var(--white);
}

.footer-bottom {
  padding-top: 40px;
  border-top: 1px solid var(--gray-800);
  text-align: center;
  font-size: 0.875rem;
}

/* Page-specific styles */
.page-hero {
  padding: 140px 0 80px;
  background: var(--gray-50);
  text-align: center;
}

.page-hero h1 {
  margin-bottom: 16px;
}

.page-hero p {
